// Chuẩn hóa dữ liệu Telegram: lấy chat_id, text, tên người dùng.
// Có nhánh fallback cho ảnh/file/sticker (không có text) để bot không bị lỗi.
const update = $input.first().json;
const message = update.message || update.edited_message || {};
const chat = message.chat || {};
const from = message.from || {};
const text = String(message.text || message.caption || '').trim();

const userName = [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'bạn';

if (!text) {
  return [{
    json: {
      chat_id: String(chat.id || ''),
      user_name: userName,
      is_supported: false,
      fallback_reply: 'Hiện em chỉ xử lý câu hỏi dạng văn bản. Anh/chị vui lòng gửi câu hỏi bằng chữ giúp em nhé.'
    }
  }];
}

return [{
  json: {
    chat_id: String(chat.id || ''),
    message_id: message.message_id,
    user_id: String(from.id || ''),
    user_name: userName,
    username: from.username || '',
    user_message: text.slice(0, 4000),
    is_supported: true,
    received_at: new Date().toISOString()
  }
}];

// Lấy câu trả lời của AI Agent, ghép lại chat_id/message_id từ node Tách Message,
// cắt độ dài cho phù hợp Telegram (~4096 ký tự) và escape ký tự HTML.
const agent = $input.first().json;
const ctx = $('⚙️ Tách Message & Chat ID').first().json;

let answer = String(agent.output || '').trim();
if (!answer) {
  answer = 'Xin lỗi, hiện em chưa tạo được câu trả lời. Anh/chị vui lòng thử lại sau hoặc liên hệ hotline để được hỗ trợ trực tiếp.';
}

// Cắt trước (3500 để chừa chỗ cho ký tự escape), sau đó escape & < > cho parse_mode=HTML.
// Node Telegram gửi với parse_mode=HTML → escape giúp tránh lỗi 'can't parse entities'
// mà vẫn hiển thị nguyên văn các ký tự Markdown (*, _, [ ]) của AI.
answer = answer.slice(0, 3500)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

return [{
  json: {
    chat_id: ctx.chat_id,
    reply_to_message_id: ctx.message_id,
    answer: answer
  }
}];
